INSERT INTO risk_templates (secteur_cnesst, libelle, categorie, agent_causal, gravite_suggeree, mesures_types, nb_cas_observes, source) VALUES ('ADMINISTRATIONS PUBLIQUES', 'REACTION DU CORPS', 'Autre risque professionnel', 'PERSONNE-TRAVAILLEUR BLESSE,MALADE', 3, 'Agent causal dominant : PERSONNE-TRAVAILLEUR BLESSE,MALADE. Nature de lésion dominante : BLES. TRAUMA. MUSCLES,TENDONS,ETC.. Siège dominant : DOS,COLONNE VERTEBRALE,MOELLE EPINI.. Gravité proposée d''après nature de lésion non reconnue, valeur médiane retenue. Observé sur 0380, 1955, 4169, 4802, 4989, 5020, 7122. À valider et compléter par l''employeur pour son établissement.', 5567, 'Données Québec — CNESST, lésions professionnelles');
